package com.ferreteriahuaman.service;
import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.dto.CustomerModels.*;import com.ferreteriahuaman.dto.SaleModels.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.ferreteriahuaman.security.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class PosCustomerServiceTest {
 CustomerRepository repo=mock(CustomerRepository.class);CustomerService customers=mock(CustomerService.class);DecolectaService external=mock(DecolectaService.class);PurchaseRepository audit=mock(PurchaseRepository.class);
 PosCustomerService service=new PosCustomerService(repo,customers,external,new ObjectMapper(),audit);
 Customer local(String state){return new Customer(3,"DNI","87654321","Nombre registrado","900000001","","Dirección registrada","0","0",state,LocalDateTime.now());}
 @Test void localCustomerAvoidsExternalCallsAndRetainsContactDetails(){when(repo.documentCustomer("87654321")).thenReturn(Optional.of(local("A")));var result=service.lookup("87654321");assertThat(result.id()).isEqualTo(3L);assertThat(result.telefono()).isEqualTo("900000001");assertThat(result.origen()).isEqualTo("REGISTRO");verifyNoInteractions(external);verify(repo,never()).create(any());}
 @Test void inactiveLocalCustomerIsNotRecreatedExternally(){when(repo.documentCustomer("87654321")).thenReturn(Optional.of(local("I")));assertThatThrownBy(()->service.lookup("87654321")).isInstanceOf(AuthFailure.class);verifyNoInteractions(external);}
 @Test void missingDniUsesReniecWithoutSaving(){when(repo.documentCustomer("87654321")).thenReturn(Optional.empty());when(external.lookupDni("87654321")).thenReturn(new DecolectaService.Dni("87654321","Persona consultada"));var result=service.lookup("87654321");assertThat(result.id()).isNull();assertThat(result.nombre()).isEqualTo("Persona consultada");assertThat(result.origen()).isEqualTo("RENIEC");verify(repo,never()).create(any());}
 @Test void missingRucIncludesFiscalDetailsWithoutSaving(){when(repo.documentCustomer("20601030013")).thenReturn(Optional.empty());when(external.lookup("20601030013")).thenReturn(new DecolectaService.Ruc("20601030013","Empresa consultada","ACTIVO","HABIDO","Dirección 123","150131","LIMA","LIMA","SAN ISIDRO"));var result=service.lookup("20601030013");assertThat(result.id()).isNull();assertThat(result.datosIdentificacion().ubigeo()).isEqualTo("150131");verify(repo,never()).create(any());}
 @Test void concurrentExistingCustomerIsReusedWithoutOverwriting(){when(repo.documentCustomer("87654321")).thenReturn(Optional.of(local("A")));var candidate=new ClientCandidate("DNI","87654321","Nombre consultado",null,null,null,null);assertThat(service.confirm(null,candidate)).isEqualTo(3);verify(repo).lockDocument("87654321");verify(repo,never()).create(any());verify(repo,never()).identification(anyLong(),anyString());verifyNoInteractions(audit);}
}
